-- Budgets cell (budgets), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA budgets;

CREATE FUNCTION budgets.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE budgets.budget_plans (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 200 AND length(name) >= 1),
    owner_scope              text NOT NULL DEFAULT 'solo_empire' CHECK (owner_scope IN ('personal', 'solo_empire', 'venture', 'client', 'shared')),
    category                 text,
    period_start             date NOT NULL,
    period_end               date NOT NULL,
    planned_amount           double precision NOT NULL CHECK (planned_amount >= 0),
    currency                 text NOT NULL DEFAULT 'THB' CHECK (length(currency) <= 12),
    status                   text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'closed', 'cancelled')),
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX budget_plans_legacy ON budgets.budget_plans (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX budget_plans_category ON budgets.budget_plans (workspace_id, category);
CREATE INDEX budget_plans_owner_scope ON budgets.budget_plans (workspace_id, owner_scope);
CREATE INDEX budget_plans_status ON budgets.budget_plans (workspace_id, status);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE budgets.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('budget-plan')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE budgets.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON budgets.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['budget_plans', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE budgets.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE budgets.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON budgets.%I'
                       ' USING (workspace_id = budgets.current_workspace())'
                       ' WITH CHECK (workspace_id = budgets.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA budgets TO budgets_api;
GRANT EXECUTE ON FUNCTION budgets.current_workspace() TO budgets_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON budgets.budget_plans TO budgets_api;
GRANT USAGE ON SEQUENCE budgets.budget_plans_id_seq TO budgets_api;
GRANT SELECT, INSERT ON budgets.create_keys TO budgets_api;
GRANT SELECT, INSERT ON budgets.outbox TO budgets_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON budgets.outbox TO budgets_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON budgets.outbox TO budgets_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA budgets TO budgets_publisher;
GRANT SELECT ON budgets.outbox TO budgets_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON budgets.outbox TO budgets_publisher;
